INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (1, 'Suelo Salinizado', 'Acumulacion excesiva de sales que afecta la capacidad del suelo para soportar cultivos.', 'high', 'soil', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (2, 'Erosion del Suelo', 'Perdida progresiva de suelo fertil por accion del agua, viento o actividad humana.', 'high', 'soil', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (3, 'Riesgo de Inundacion', 'Zona susceptible a encharcamientos y desbordamientos durante temporadas de lluvia.', 'high', 'water', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (4, 'Aguas Estancadas', 'Presencia de agua acumulada que favorece la proliferacion de vectores de enfermedades.', 'medium', 'water', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (5, 'Aridez Climatica', 'Deficit hidrico severo que limita el desarrollo de actividades agricolas.', 'medium', 'climate', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (6, 'Contaminacion Petrolera', 'Degradacion del suelo por presencia de hidrocarburos y derivados del petroleo.', 'high', 'pollution', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (7, 'Baja Fertilidad', 'Suelos pobres en nutrientes esenciales para el crecimiento de plantas.', 'medium', 'soil', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (8, 'Topografia Accidentada', 'Terrenos con pendientes pronunciadas que dificultan el uso agricola.', 'medium', 'terrain', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (9, 'Areas Quemadas', 'Areas afectadas por incendios que han degradado la capa vegetal y organica.', 'high', 'fire', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (10, 'Deforestacion', 'Perdida de cobertura forestal que aumenta la vulnerabilidad del ecosistema.', 'high', 'environmental', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (11, 'Sequia', 'Periodos prolongados sin precipitaciones que afectan la disponibilidad de agua.', 'high', 'climate', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (12, 'Plagas y Enfermedades', 'Presencia de organismos que danan cultivos y reducen la productividad.', 'medium', 'biological', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (13, 'Suelo Blando', 'Suelos con baja capacidad de carga que ceden bajo presion, riesgo de hundimiento.', 'high', 'soil', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (14, 'Deslizamientos', 'Zonas con riesgo de movimiento de masas de tierra por pendiente o saturacion.', 'high', 'terrain', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (15, 'Contaminacion del Agua', 'Presencia de agentes contaminantes en fuentes de agua superficial o subterranea.', 'high', 'water', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (16, 'Contaminacion por Mercurio', 'Presencia de mercurio por mineria de oro ilegal o industrial. Afecta suelos, rios y salud humana.', 'high', 'mining', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (17, 'Relaves Mineros', 'Depositos de residuos solidos de procesos mineros con alto contenido de metales pesados y quimicos.', 'high', 'mining', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (18, 'Subsidencia del Suelo', 'Hundimiento progresivo del terreno por extraccion subterranea de minerales o hidrocarburos.', 'high', 'mining', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (19, 'Contaminacion por Metales Pesados', 'Acumulacion de plomo, cadmio, arsenico u otros metales toxicos por actividad extractiva.', 'high', 'mining', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (20, 'Deforestacion Minera', 'Perdida de cobertura vegetal causada directamente por apertura de minas o vias de acceso.', 'high', 'mining', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (21, 'Contaminacion de Acuiferos', 'Infiltracion de quimicos mineros en aguas subterraneas que abastecen comunidades.', 'high', 'mining', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (22, 'Riesgo de Explosion', 'Zonas con uso de explosivos en actividades mineras activas o abandonadas.', 'high', 'mining', true);
INSERT INTO factores_riesgo (id, nombre, descripcion, nivel, categoria, activo) VALUES (23, 'Mineria Ilegal Activa', 'Presencia de actividad extractiva sin control ambiental ni regulacion estatal en la zona.', 'high', 'mining', true);
